// Editing is restricted to the tactics dialog; live pitch stays read-only.
var tacticalDrag=null;
function tacticalDropPoint(rect,x,y){return [Math.max(7,Math.min(93,Math.round((x-rect.left)/rect.width*100))),Math.max(8,Math.min(92,Math.round((y-rect.top)/rect.height*100)))];}
// Position names describe placement only; natural registration and saved match rules stay stable.
const tacticalSlots=[['LW',16,20,'왼쪽 윙어'],['LS',35,20,'왼쪽 스트라이커'],['ST',50,17,'중앙 스트라이커'],['RS',65,20,'오른쪽 스트라이커'],['RW',84,20,'오른쪽 윙어'],['LAM',18,32,'왼쪽 공격형 미드필더'],['AM',50,31,'공격형 미드필더'],['RAM',82,32,'오른쪽 공격형 미드필더'],['LM',15,44,'왼쪽 미드필더'],['LCM',35,47,'왼쪽 중앙 미드필더'],['CM',50,49,'중앙 미드필더'],['RCM',65,47,'오른쪽 중앙 미드필더'],['RM',85,44,'오른쪽 미드필더'],['LWB',12,59,'왼쪽 윙백'],['LDM',35,59,'왼쪽 수비형 미드필더'],['DM',50,59,'수비형 미드필더'],['RDM',65,59,'오른쪽 수비형 미드필더'],['RWB',88,59,'오른쪽 윙백'],['LB',15,70,'왼쪽 풀백'],['LCB',35,74,'왼쪽 중앙 수비수'],['CB',50,76,'중앙 수비수'],['RCB',65,74,'오른쪽 중앙 수비수'],['RB',85,70,'오른쪽 풀백']].map(([code,x,y,label])=>({code,x,y,label}));
function tacticalPosition(x,y,natural){if(natural==='GK')return {code:'GK',label:'골키퍼'};return tacticalSlots.reduce((a,b)=>Math.hypot(a.x-x,a.y-y)<=Math.hypot(b.x-x,b.y-y)?a:b);}
function tacticalSnapPoint(id,point){
 if(state.players[id].pos==='GK')return [50,88];
 const targets=[...positions().filter(r=>r.p.pos!=='GK').map(r=>[r.x,r.y]),...tacticalSlots.map(r=>[r.x,r.y])];
 return targets.reduce((a,b)=>Math.hypot(a[0]-point[0],a[1]-point[1])<=Math.hypot(b[0]-point[0],b[1]-point[1])?a:b);
}
function tacticalZoneMarkup(){return '<div class="tactical-slots" aria-hidden="true">'+tacticalSlots.map(r=>'<span data-tactical-slot="'+r.code+'" style="left:'+r.x+'%;top:'+r.y+'%">'+r.code+'</span>').join('')+'</div><span class="tactical-keeper-zone" aria-hidden="true">GK 전용 · 이동 불가</span>';}
function commitTacticalPosition(id,point){
 if(!editable()||!state.lineup.includes(id)||state.players[id].pos==='GK')return;
 const rows=positions(),origin=rows.find(r=>r.id===id),p=state.players[id];point=tacticalSnapPoint(id,point);
 const occupant=rows.find(r=>r.id!==id&&r.p.pos!=='GK'&&Math.hypot(r.x-point[0],r.y-point[1])<1);
 if(occupant)customPositions[occupant.p.identity]=[origin.x,origin.y];
 customPositions[p.identity]=[...point];selected=id;save();render();
 const pos=tacticalPosition(...point,p.pos);$('tactical-position-status').textContent=p.name+' · '+pos.code+' '+pos.label+(occupant?' · '+occupant.p.name+'과 자리 교환':' 배치 완료');
 $('tactical-editor').querySelector('[data-tactical-player="'+id+'"]')?.focus({preventScroll:true});
}
function tacticalTraitMarkup(row){
 if(!row)return '';
 const p=row.p,position=tacticalPosition(row.x,row.y,p.pos),fit=PlayerTraits.suitability(p,F.assignedPosition(row.x,row.y,p.pos).code),feet=PlayerTraits.feet(p),form=PlayerTraits.condition(season,p);
 const top=PlayerTraits.allPositions(p).filter(pos=>pos.code!=='GK'||p.pos==='GK').sort((a,b)=>b.score-a.score||a.code.localeCompare(b.code)).slice(0,4);
 return '<div class="tactical-selected-profile"><strong>'+escapeText(p.name)+' · 현재 '+position.code+' 적합도 '+fit+'</strong><p>주발 '+escapeText(feet.label)+' · 왼발 '+feet.left+'/5 · 오른발 '+feet.right+'/5 · 컨디션 '+escapeText(form.label)+(form.score===null?'':' '+form.score)+'</p><div>'+top.map(pos=>'<span>'+pos.code+' '+pos.score+'</span>').join('')+'</div><small>포지션 적합도는 전술 선택을 돕는 코치 분석입니다.</small></div>';
}
function setPieceAssignmentMarkup(canEdit){
 if(!state||state.version<8||!state.setPieces)return '';
 const roles=Object.entries(F.setPieceRoleNames),field=state.lineup.map(id=>state.players[id]).filter(p=>p&&p.pos!=='GK'&&F.isAvailable(p)&&!Discipline.dismissed(state).includes(p.id));
 return '<section class="set-piece-plan" aria-labelledby="set-piece-plan-title"><div><span class="eyebrow">세트피스 준비</span><h3 id="set-piece-plan-title">세트피스 키커와 타깃</h3><p>상대 수비를 흔들 준비를 하세요. 코너와 직접 프리킥이 경기 장면·기대 득점에 반영됩니다.</p></div>'+roles.map(([role,label])=>{const assigned=field.find(p=>p.id===state.setPieces[role])||state.players[F.defaultSetPieces(state,field.map(p=>p.id))[role]],preference=state===season.match?season.plan.setPieces?.[role]:null,person=preference?F.identityProfile(preference):null,fallback=person&&person.identity!==assigned?.identity,options=[...field].sort((a,b)=>F.setPieceScore(b,role)-F.setPieceScore(a,role)||a.id.localeCompare(b.id));return '<label class="set-piece-role"><span>'+label+'<small>'+escapeText(person?(fallback?person.name+' 대신 이번 경기 대체':'우선 담당: '+person.name):'이번 선발에서 자동 선택')+'</small></span><select data-set-piece-role="'+role+'" aria-label="'+label+' 선택" '+(!canEdit||state.phase!=='prep'?'disabled':'')+'><option value="auto">자동 선택으로 변경</option>'+options.map(p=>'<option value="'+p.id+'" '+(p.id===assigned?.id?'selected':'')+'>'+escapeText(p.name)+' · '+p.pos+' · '+F.setPieceScore(p,role)+'</option>').join('')+'</select></label>';}).join('')+'<p class="set-piece-note">영입 선수도 선발에 넣은 뒤 지정할 수 있습니다. 지정은 선수 신원으로 다음 경기까지 기억합니다. 후보·부상·출전 정지 때는 대체 선수가 맡고, 다시 선발에 들면 우선 담당이 돌아옵니다. 이적하면 지정이 해제됩니다. 경기 중 교체·퇴장은 현재 필드에서 자동 대체합니다. 지표는 현재 공격·패스·수비·스피드·지구력으로 계산합니다.</p></section>';
}
function renderTacticalEditor(){
 const host=$('tactical-editor');if(!host||!state||tacticalDrag)return;
 const briefingOpen=Boolean(host.querySelector('.touchline-briefing')?.open),canEdit=editable(),rows=positions().filter(row=>!Discipline.dismissed(state).includes(row.id)),chosen=rows.find(row=>row.id===selected),plan=TouchlinePlan.read(season,rows.map(r=>({...r,roleFit:typeof roleSuitability==='function'?roleSuitability(r.p,playerRole(r.p)[0]):undefined,roleName:typeof playerRole==='function'?playerRole(r.p)[1]:undefined})),selected);
 host.innerHTML='<h3>선수 배치와 역할</h3><p>LS·RS와 미드필더·수비 자리에 선수를 놓으세요. 동료가 있는 자리에 놓으면 두 선수의 자리가 바뀝니다. 골키퍼는 고정입니다. 방향키로도 이동할 수 있습니다.</p><div class="tactical-team-strip">선발 종합 평균 <b>'+plan.team.overall+'</b> · 체력 평균 <b>'+plan.team.energy+'</b></div><label class="support-map-toggle"><input id="support-map-toggle" type="checkbox" '+(supportMapVisible?'checked':'')+'/> 가까운 동료 연결 표시</label><div class="tactical-pitch" role="group" aria-label="드래그로 선수 배치 · 공격 방향 위쪽">'+tacticalZoneMarkup()+(supportMapVisible?supportMapSvg(plan):'')+'<span class="tactical-direction" aria-hidden="true">공격 방향 ↑</span>'+rows.map(({id,p,x,y})=>{const pos=tacticalPosition(x,y,p.pos),rating=TouchlinePlan.overall(p),energy=Math.round(p.energy),fit=PlayerTraits.suitability(p,F.assignedPosition(x,y,p.pos).code),form=PlayerTraits.condition(season,p);return '<button type="button" data-tactical-player="'+id+'" aria-label="'+escapeText(p.name+' · '+pos.code+' '+pos.label+' · 종합 '+rating+' · 체력 '+energy+' · 배치 적합도 '+fit+' · 컨디션 '+form.label+(p.pos==='GK'?' · GK 위치 고정':' · 방향키로 이동'))+'" aria-pressed="'+(selected===id)+'" '+(!canEdit?'disabled':'')+' style="left:'+x+'%;top:'+y+'%">'+Portraits.html(p)+'<b>'+p.no+' <em>'+pos.code+'</em></b><span class="tactical-full-name" aria-hidden="true">'+escapeText(p.name)+'</span><span class="tactical-short-name" aria-hidden="true">'+escapeText(p.name.trim().split(/\s+/).at(-1))+'</span></button>';}).join('')+'</div><p id="tactical-position-status" role="status" aria-live="polite">'+(chosen?escapeText(chosen.p.name)+' · 배치 '+tacticalPosition(chosen.x,chosen.y,chosen.p.pos).code+' · 주 포지션 '+chosen.p.pos:'빈 포지션에 배치 · 동료 자리에 놓으면 교환 · GK 고정')+'</p>'+tacticalTraitMarkup(chosen)+setPieceAssignmentMarkup(canEdit)+touchlineMarkup(plan)+'<p class="tactical-note">배치 포지션은 경기장의 출발 위치입니다. 선수의 주 포지션과 교체 등록 포지션은 유지됩니다. 포메이션을 바꾸면 새 기본 배치로 정렬합니다.</p>';
 const briefing=host.querySelector('.touchline-briefing');if(briefing)briefing.open=briefingOpen;
 host.onchange=event=>{if(event.target.matches('[data-set-piece-role]')){const role=event.target.dataset.setPieceRole;if(state!==season.match)F.assignSetPieceRole(state,role,event.target.value==='auto'?F.defaultSetPieces(state,state.lineup)[role]:event.target.value);else if(event.target.value==='auto')S.autoSetPiece(season,role);else S.assignSetPiece(season,role,event.target.value);save();render();$('tactical-editor').querySelector('[data-set-piece-role="'+role+'"]')?.focus({preventScroll:true});return;}if(event.target.id!=='support-map-toggle')return;supportMapVisible=event.target.checked;renderTacticalEditor();$('support-map-toggle')?.focus({preventScroll:true});};
 host.onclick=event=>{const b=event.target.closest('[data-tactical-player]');if(!b||!canEdit||tacticalDrag)return;selected=b.dataset.tacticalPlayer;save();render();host.querySelector('[data-tactical-player="'+selected+'"]')?.focus({preventScroll:true});};
 host.onpointerdown=event=>{const b=event.target.closest('[data-tactical-player]');if(!b||!canEdit||event.button!==0||tacticalDrag)return;const row=rows.find(row=>row.id===b.dataset.tacticalPlayer);selected=row.id;if(row.p.pos==='GK'){$('tactical-position-status').textContent=row.p.name+' · 골키퍼 전용 위치입니다. 이동할 수 없습니다.';return;}tacticalDrag={id:row.id,pointer:event.pointerId,button:b,rect:b.parentElement.getBoundingClientRect(),point:[row.x,row.y]};b.setPointerCapture(event.pointerId);b.classList.add('dragging');const map=host.querySelector('.support-map');if(map)map.style.visibility='hidden';event.preventDefault();};
 host.onpointermove=event=>{const d=tacticalDrag;if(!d||event.pointerId!==d.pointer)return;d.point=tacticalSnapPoint(d.id,tacticalDropPoint(d.rect,event.clientX,event.clientY));host.querySelectorAll('[data-tactical-slot]').forEach(cell=>cell.classList.toggle('active',cell.dataset.tacticalSlot===tacticalPosition(...d.point,state.players[d.id].pos).code));d.button.style.left=d.point[0]+'%';d.button.style.top=d.point[1]+'%';const p=state.players[d.id],pos=tacticalPosition(...d.point,p.pos);d.button.querySelector('em').textContent=pos.code;$('tactical-position-status').textContent=p.name+' · '+pos.code+' '+pos.label;event.preventDefault();};
 host.onpointerup=event=>{const d=tacticalDrag;if(!d||event.pointerId!==d.pointer)return;tacticalDrag=null;d.button.releasePointerCapture(event.pointerId);commitTacticalPosition(d.id,d.point);};
 host.onpointercancel=host.onlostpointercapture=event=>{if(!tacticalDrag||event.pointerId!==tacticalDrag.pointer)return;tacticalDrag=null;render();};
 host.onkeydown=event=>{const b=event.target.closest('[data-tactical-player]'),delta={ArrowLeft:[-34,0],ArrowRight:[34,0],ArrowUp:[0,-27],ArrowDown:[0,27]}[event.key];if(!b||!delta||!canEdit)return;event.preventDefault();const row=positions().find(row=>row.id===b.dataset.tacticalPlayer);commitTacticalPosition(row.id,[Math.max(7,Math.min(93,row.x+delta[0])),Math.max(8,Math.min(92,row.y+delta[1]))]);};
}
const tacticalEditorHost=document.createElement('section');tacticalEditorHost.id='tactical-editor';$('match-popup-tactics').prepend(tacticalEditorHost);
